/**
 * safe-supabase.mjs
 *
 * Supabase client wrapper that blocks all write operations unless the caller
 * has explicitly called consumeWriteToken() with operation metadata that
 * matches a token generated by the human.
 *
 * Architecture:
 *   - requireWriteToken (from require-write-token.mjs) verifies the token.
 *   - consumeWriteToken here marks the token as "used" so the same token
 *     can't authorize two writes (one UPDATE, one DELETE) in the same
 *     10-minute window.
 *   - createSafeClient() returns a Proxy-wrapped Supabase client where
 *     .update(), .delete(), .upsert(), .insert() throw unless a token has
 *     been consumed for this operation.
 *
 * Usage:
 *   import { createSafeClient, consumeWriteToken } from './safe-supabase.mjs';
 *   const supabase = createSafeClient(url, serviceKey);
 *   // Reading is unrestricted:
 *   const { data } = await supabase.from('rinks').select('*');
 *   // Writing requires explicit token consumption first:
 *   await consumeWriteToken({ operation: 'update', table: 'rinks', estimatedRows: 718 });
 *   await supabase.from('rinks').update({ ... }).eq('is_active', true);
 */

import { createClient } from '@supabase/supabase-js';
import { requireWriteToken } from './require-write-token.mjs';

class WriteBlockedError extends Error {
  constructor(message) {
    super(message);
    this.name = 'WriteBlockedError';
  }
}

// Set of "operation:table:estimatedRows" strings that have been authorized
// in this process. Cleared when the process exits.
const consumedTokens = new Set();

/**
 * Consume a write token for a specific operation. Must be called BEFORE
 * the write itself. The token file must exist with a matching hash, and
 * the token can only be used once per process.
 *
 * @param {object} params
 * @param {string} params.operation - 'update' | 'delete' | 'upsert' | 'insert'
 * @param {string} params.table - Table name being written to
 * @param {number} params.estimatedRows - Number of rows the write will affect
 */
export async function consumeWriteToken({ operation, table, estimatedRows }) {
  requireWriteToken({ operation, table, estimatedRows });
  const key = `${operation}:${table}:${estimatedRows}`;
  if (consumedTokens.has(key)) {
    throw new WriteBlockedError(
      `Write blocked. Token for ${key} already consumed in this process. ` +
      `Each operation needs its own token.`,
    );
  }
  consumedTokens.add(key);
}

/**
 * Create a Supabase client where write operations are gated by consumed tokens.
 * Reading is unrestricted.
 */
export function createSafeClient(url, serviceKey, options = {}) {
  const client = createClient(url, serviceKey, options);

  const writeMethods = ['update', 'delete', 'upsert', 'insert'];
  const tableFromBuilder = (builder) => {
    // Supabase query builder pattern: .from(table) returns a builder.
    // The builder has chained methods. We can't easily extract the table
    // name from the builder because it's stored as a closure in the
    // internal implementation. Instead, the caller MUST call
    // consumeWriteToken({ table: 'tableName', ... }) BEFORE the write,
    // and we track which (op, table) pairs have been authorized.
    return builder;
  };

  // Wrap from() so we can intercept the chained calls
  const originalFrom = client.from.bind(client);
  const fromProxy = new Proxy({}, {
    get(_target, prop) {
      if (typeof prop === 'symbol') return undefined;
      if (prop === 'then') return undefined; // not a thenable
      // For now, return a passthrough that the chained call will use.
      // The actual gating happens via consumedTokens check in the write methods.
      return (...args) => {
        const subBuilder = originalFrom(prop)[args[0]?.name || ''];
        return subBuilder;
      };
    },
  });

  // The cleanest approach: intercept .from() and wrap the resulting builder.
  client.from = function (table) {
    const originalBuilder = originalFrom(table);

    return new Proxy(originalBuilder, {
      get(target, prop, receiver) {
        if (writeMethods.includes(prop)) {
          // Return a function that requires a consumed token for this (op, table).
          return (data, options) => {
            const op = prop;
            const key = `${op}:${table}:0`; // row count unknown at this layer
            // We don't know estimatedRows here without additional plumbing.
            // The token must have been consumed with this exact (op, table)
            // regardless of row count. We check the consumedTokens set.
            const found = Array.from(consumedTokens).find((k) => k.startsWith(`${op}:${table}:`));
            if (!found) {
              throw new WriteBlockedError(
                `Write blocked. No consumed token found for ${op} on table '${table}'. ` +
                `Call consumeWriteToken({ operation: '${op}', table: '${table}', estimatedRows: N }) first.`,
              );
            }
            // Mark this token as used so it can't authorize a second write.
            consumedTokens.delete(found);
            return target[prop](data, options);
          };
        }
        // Non-write methods (select, eq, order, etc.) are passed through.
        const value = Reflect.get(target, prop, receiver);
        if (typeof value === 'function') {
          return value.bind(target);
        }
        return value;
      },
    });
  };

  return client;
}

export { WriteBlockedError };